Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
`) as reject routes when the device is loopback. This causes the code to skip `fib_nh_common_init()`, leaving `nhc_pcpu_rth_output` unallocated. Later, when an IPv4 route references such a nexthop, dereferencing the uninitialized pointer leads to a panic. The bug was introduced by the use of the overly broad `fib6_is_reject()` check instead of the more specific `RTF_REJECT` flag check.

Here is the patch:

 int fib6_nh_init(struct net *net, struct fib6_nh *fib6_nh,
 		 struct fib6_config *cfg, gfp_t gfp_flags,
 		 struct netlink_ext_ack *extack)
 {
 	netdevice_tracker *dev_tracker = &fib6_nh->fib_nh_dev_tracker;
 	struct net_device *dev = NULL;
 	struct inet6_dev *idev = NULL;
-	int addr_type;
 	int err;

 	fib6_nh->fib_nh_family = AF_INET6;
 #ifdef CONFIG_IPV6_ROUTER_PREF
 	fib6_nh->last_probe = jiffies;
 #endif
 	if (cfg->fc_is_fdb) {
 		fib6_nh->fib_nh_gw6 = cfg->fc_gateway;
 		fib6_nh->fib_nh_gw_family = AF_INET6;
 		return 0;
 	}

 	err = -ENODEV;
 	if (cfg->fc_ifindex) {
 		dev = netdev_get_by_index(net, cfg->fc_ifindex,
 					  dev_tracker, gfp_flags);
 		if (!dev)
 			goto out;
 		idev = in6_dev_get(dev);
 		if (!idev)
 			goto out;
 	}

 	if (cfg->fc_flags & RTNH_F_ONLINK) {
 		if (!dev) {
 			NL_SET_ERR_MSG(extack,
 				       "Nexthop device required for onlink");
 			goto out;
 		}

 		if (!(dev->flags & IFF_UP)) {
 			NL_SET_ERR_MSG(extack, "Nexthop device is not up");
 			err = -ENETDOWN;
 			goto out;
 		}

 		fib6_nh->fib_nh_flags |= RTNH_F_ONLINK;
 	}

 	fib6_nh->fib_nh_weight = 1;

-	/* We cannot add true routes via loopback here,
-	 * they would result in kernel looping; promote them to reject routes
+	/* Reset the nexthop device to the loopback device in case of reject
+	 * routes.
 	 */
-	addr_type = ipv6_addr_type(&cfg->fc_dst);
-	if (fib6_is_reject(cfg->fc_flags, dev, addr_type)) {
+	if (cfg->fc_flags & RTF_REJECT) {
 		/* hold loopback dev/idev if we haven't done so. */
 		if (dev != net->loopback_dev) {
 			if (dev) {
 				netdev_put(dev, dev_tracker);
 				in6_dev_put(idev);
 			}
 			dev = net->loopback_dev;
 			netdev_hold(dev, dev_tracker, gfp_flags);
 			idev = in6_dev_get(dev);
 			if (!idev) {
 				err = -ENODEV;
 				goto out;
 			}
 		}
 		goto pcpu_alloc;
 	}

 	if (cfg->fc_flags & RTF_GATEWAY) {
 		err = ip6_validate_gw(net, cfg, &dev, dev_tracker,
 				      &idev, extack);
 		if (err)
 			goto out;

 		fib6_nh->fib_nh_gw6 = cfg->fc_gateway;
 		fib6_nh->fib_nh_gw_family = AF_INET6;
 	}

 	err = -ENODEV;
 	if (!dev)
 		goto out;

 	if (!idev || idev->cnf.disable_ipv6) {
 		NL_SET_ERR_MSG(extack, "IPv6 is disabled on nexthop device");
 		err = -EACCES;
 		goto out;
 	}

 	if (!(dev->flags & IFF_UP) && !cfg->fc_ignore_dev_down) {
 		NL_SET_ERR_MSG(extack, "Nexthop device is not up");
 		err = -ENETDOWN;
 		goto out;
 	}

 	if (!(cfg->fc_flags & (RTF_LOCAL | RTF_ANYCAST)) &&
 	    !netif_carrier_ok(dev))
 		fib6_nh->fib_nh_flags |= RTNH_F_LINKDOWN;

 	err = fib_nh_common_init(net, &fib6_nh->nh_common, cfg->fc_encap,
 				 cfg->fc_encap_type, cfg, gfp_flags, extack);
 	if (err)
 		goto out;

 pcpu_alloc:
 	fib6_nh->rt6i_pcpu = alloc_percpu_gfp(struct rt6_info *, gfp_flags);
 	if (!fib6_nh->rt6i_pcpu) {
 		err = -ENOMEM;
 		goto out;
 	}

 	fib6_nh->fib_nh_dev = dev;
 	fib6_nh->fib_nh_oif = dev->ifindex;
 	err = 0;
 out:
 	if (idev)
 		in6_dev_put(idev);

 	if (err) {
 		fib_nh_common_release(&fib6_nh->nh_common);
 		fib6_nh->nh_common.nhc_pcpu_rth_output = NULL;
 		fib6_nh->fib_nh_lws = NULL;
 		netdev_put(dev, dev_tracker);
 	}

 	return err;
 }



